#include <algorithm>
#include <array>
#include <cassert>
#include <iostream>
#include <map>
#include <numeric>
#include <vector>

#ifndef CRT_COLUMNS
#define CRT_COLUMNS 4
#endif

constexpr int columns = CRT_COLUMNS;
constexpr int cells = 3 * columns;
constexpr int vertices = 3 + columns;
static_assert(columns == 4 || columns == 5);
using Table = std::array<int, cells>;
using Margin = std::array<int, vertices>;
using Row = std::array<int, columns>;
using Stats = std::array<int, 3>;

int pop(unsigned v) { return __builtin_popcount(v); }

struct Cycle {
    unsigned positive = 0;
    unsigned negative = 0;
    int coefficient(int i) const {
        return int((positive >> i) & 1) - int((negative >> i) & 1);
    }
    int effect(unsigned m) const { return pop(m & positive) - pop(m & negative); }
};

struct Point {
    Table num;
    Margin margin;
};

struct Support {
    unsigned mask;
    std::vector<Cycle> cycles;
    std::map<int, std::vector<Point>> by_denominator;
};

int row_vertex(int edge) { return edge / columns; }
int col_vertex(int edge) { return 3 + edge % columns; }

std::vector<Support> enumerate_supports() {
    std::vector<Support> result;
    for(unsigned bits=0; bits<(1u<<cells); ++bits) {
        const int size=pop(bits);
        if(size < 2*columns || size > columns+5) continue;
        Margin degree{};
        for(int e=0;e<cells;++e)if((bits >> e)&1) {
            ++degree[row_vertex(e)];
            ++degree[col_vertex(e)];
        }
        if(*std::min_element(degree.begin(),degree.end())<2) continue;

        std::array<int,vertices> leader;
        std::iota(leader.begin(),leader.end(),0);
        auto root=[&](int v){while(leader[v]!=v) v=leader[v]; return v;};
        std::array<std::vector<std::pair<int,int>>,vertices> tree;
        std::vector<int> chords;
        for(int e=0;e<cells;++e)if((bits >> e)&1) {
            const int i=row_vertex(e), j=col_vertex(e);
            const int a=root(i), b=root(j);
            if(a==b) chords.push_back(e);
            else {
                leader[b]=a;
                tree[i].push_back({j,e});
                tree[j].push_back({i,e});
            }
        }
        assert(chords.size()==unsigned(size-(vertices-1)));
        Support support{bits,{},{}};
        for(int e:chords){
            Cycle cycle{};
            cycle.positive=1u<<e;
            const int source=row_vertex(e), target=col_vertex(e);
            auto path=[&](auto&& self,int at,int parent,bool negative)->bool{
                if(at==target)return true;
                for(auto [next,edge]:tree[at]) if(next!=parent &&
                    self(self,next,at,!negative)) {
                    if(negative)cycle.negative|=1u<<edge;
                    else cycle.positive|=1u<<edge;
                    return true;
                }
                return false;
            };
            assert(path(path,source,-1,true));
            Margin balance{};
            for(int j=0;j<cells;++j){
                balance[row_vertex(j)]+=cycle.coefficient(j);
                balance[col_vertex(j)]+=cycle.coefficient(j);
            }
            assert(balance==Margin{});
            for(int f:chords) assert(cycle.coefficient(f)==int(e==f));
            support.cycles.push_back(cycle);
        }
        result.push_back(support);
    }
    return result;
}

int determinant_divisor(const std::vector<Cycle>& cycles,const std::array<unsigned,3>& masks) {
    std::array<Stats,3> a{};
    for(int i=0;i<3;++i)for(unsigned j=0;j<cycles.size();++j) a[i][j]=cycles[j].effect(masks[i]);
    if(cycles.size()==2) {
        int d=0;
        for(int i=0;i<3;++i) for(int j=i+1;j<3;++j)
            d=std::gcd(d,a[i][0]*a[j][1]-a[i][1]*a[j][0]);
        return d;
    }
    return std::abs(a[0][0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1])
                  -a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0])
                  +a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0]));
}

const std::vector<Point>& points_for(Support& support,int d) {
    auto [entry,fresh]=support.by_denominator.try_emplace(d);
    if(!fresh)return entry->second;
    auto& dest=entry->second;
    Table vector{};
    auto visit=[&](auto&& self,unsigned i)->void {
        if(i==support.cycles.size()){
            Table y{};
            Margin m{};
            for(int e=0;e<cells;++e) if((support.mask>>e)&1){
                const int v=(vector[e]%d+d)%d;
                if(v==0)return;
                y[e]=v;
                m[row_vertex(e)]+=v;
                m[col_vertex(e)]+=v;
            }
            for(int &v:m){assert(v%d==0);v/=d;}
            dest.push_back({y,m});
            return;
        }
        const Cycle& c=support.cycles[i];
        for(int k=1;k<d;++k){
            for(int e=0;e<cells;++e)vector[e]+=c.coefficient(e);
            self(self,i+1);
        }
        for(int e=0;e<cells;++e)vector[e]-=(d-1)*c.coefficient(e);
    };
    visit(visit,0);
    return dest;
}

std::vector<Table> integral_tables(const Margin& totals) {
    Table x{};
    Margin remaining=totals;
    std::vector<Table> result;
    auto visit=[&](auto&& self,int e)->void {
        if(e==cells) {
            assert(remaining==Margin{});
            result.push_back(x);
            return;
        }
        const int r=row_vertex(e), c=col_vertex(e);
        const int last_col=remaining[r], last_row=remaining[c];
        int lo=0,hi=std::min(last_col,last_row);
        if(e%columns==columns-1) lo=hi=last_col;
        if(e/columns==2) lo=hi=last_row;
        if(hi>last_col || hi>last_row || (e==cells-1 && last_col!=last_row))return;
        for(int v=lo;v<=hi;++v) {
            x[e]=v;
            remaining[r]-=v;remaining[c]-=v;
            self(self,e+1);
            remaining[r]+=v;remaining[c]+=v;
        }
    };
    visit(visit,0);
    return result;
}

Stats measure(const Table& x,const std::array<unsigned,3>& masks) {
    Stats out{};
    for(int e=0;e<cells;++e) for(int j=0;j<3;++j)
        if((masks[j]>>e)&1)out[j]+=x[e];
    return out;
}

std::vector<Row> row_categories() {
    std::vector<Row> out;
    Row row{};
    auto visit = [&](auto&& self,int j)->void {
        if(j==columns) { out.push_back(row); return; }
        const int first = j ? row[j-1] : 0;
        const int last = j ? std::min(5,row[0]+3) : 5;
        for(int key=first; key<=last; ++key) {
            row[j]=key;
            self(self,j+1);
        }
    };
    visit(visit,0);
    return out;
}

std::array<unsigned,3> masks_of(const Table& category) {
    std::array<unsigned,3> masks{};
    for(int i=0;i<cells;++i){
        auto c=category[i];
        if(c>=3)masks[0]|=1u<<i;
        if(c%3==0)masks[1]|=1u<<i;
        if(c%3!=2)masks[2]|=1u<<i;
    }
    return masks;
}

int main() {
    auto supports=enumerate_supports();
    const auto rows=row_categories();
    std::map<Margin,std::vector<Table>> integral;
    long long type_count=0, holes=0;
    std::map<int,long long> divisors, checked;
    std::map<int,int> by_size;
    for(const auto& support : supports) ++by_size[pop(support.mask)];
    for(const auto& a:rows)for(const auto& b:rows)for(const auto& c:rows) {
        bool admissible=true;
        for(int j=0;j<columns;++j)if(a[j]>b[j] || b[j]>c[j] || c[j]-a[j]>3)admissible=false;
        if(!admissible)continue;
        ++type_count;
        Table category{};
        std::copy(a.begin(),a.end(),category.begin());
        std::copy(b.begin(),b.end(),category.begin()+columns);
        std::copy(c.begin(),c.end(),category.begin()+2*columns);
        const auto masks=masks_of(category);
        std::map<Margin,std::vector<Stats>> integer_views;
        bool hole=false;
        for(auto& support:supports) {
            const int d=determinant_divisor(support.cycles,masks);
            ++divisors[d];
            if(d<=1)continue;
            for(const Point& point:points_for(support,d)){
                Stats y=measure(point.num,masks);
                if(std::any_of(y.begin(),y.end(),[&](int z){return z%d!=0;}))continue;
                ++checked[d];
                for(auto& z:y)z/=d;
                if(!integer_views.count(point.margin)){
                    if(!integral.count(point.margin))
                        integral.emplace(point.margin,integral_tables(point.margin));
                    auto& view=integer_views[point.margin];
                    for(const auto& x:integral[point.margin])view.push_back(measure(x,masks));
                }
                const auto& view=integer_views.at(point.margin);
                if(std::find(view.begin(),view.end(),y)!=view.end())continue;
                ++holes;hole=true;
                for(int v:category)std::cout<<v<<' ';
                std::cout<<d<<' ';
                for(int v:point.num)std::cout<<v<<' ';
                std::cout<<'\n';
                break;
            }
            if(hole)break;
        }
    }
    std::cout << "columns=" << columns << " types=" << type_count
              << " supports=" << supports.size() << " holes=" << holes << '\n';
    for(auto [size,count] : by_size)
        std::cout << "fractional_edges=" << size << " supports=" << count << '\n';
    for(auto [d,count]:divisors)
        std::cout << "divisor=" << d << " support_pairs=" << count
                  << " fractional_points_recovered=" << checked[d] << '\n';
    if(holes) return 1;
    long long total=0;
    for(auto [d,count]:divisors)total+=count;
    if(columns==4) assert(type_count==27062 && supports.size()==150);
    if(columns==5) assert(type_count==114680 && supports.size()==210);
    assert(total==type_count*static_cast<long long>(supports.size()));
}

// Exact unit-matching spectra on monotone nested threshold triples.
#include <algorithm>
#include <array>
#include <bit>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <vector>

using Mask = std::uint64_t;
constexpr int MAX_WIDTH = 6;

struct Coverage {
    std::uint64_t ferrers = 0;
    std::uint64_t outer_pairs = 0;
    std::uint64_t triples = 0;
    std::uint64_t matching_evaluations = 0;
    std::uint64_t integer_slices = 0;
    std::uint64_t chord_checks = 0;
};

void make_ferrers(int width, int row, int previous_cut, Mask mask,
                  std::vector<Mask>& out) {
    if (row == width) {
        out.push_back(mask);
        return;
    }
    for (int cut = 0; cut <= previous_cut; ++cut) {
        Mask tail = 0;
        for (int col = cut; col < width; ++col) {
            tail |= Mask{1} << (row * width + col);
        }
        make_ferrers(width, row + 1, cut, mask | tail, out);
    }
}

std::vector<Mask> unit_matchings(int width) {
    std::vector<int> columns(width);
    std::iota(columns.begin(), columns.end(), 0);
    std::vector<Mask> result;
    do {
        Mask matching = 0;
        for (int row = 0; row < width; ++row) {
            matching |= Mask{1} << (row * width + columns[row]);
        }
        result.push_back(matching);
    } while (std::next_permutation(columns.begin(), columns.end()));
    return result;
}

void check_spectrum(int width, Mask carry, Mask prefix,
                    const std::vector<Mask>& matchings, Coverage& coverage) {
    std::array<unsigned, MAX_WIDTH + 1> observed{};
    for (Mask matching : matchings) {
        const int e = std::popcount(matching & carry);
        const int p = std::popcount(matching & prefix);
        observed[e] |= 1u << p;
    }

    std::array<int, MAX_WIDTH + 1> low{}, high{};
    for (int e = 0; e <= width; ++e) {
        if (!observed[e]) continue;
        low[e] = std::countr_zero(observed[e]);
        high[e] = std::bit_width(observed[e]) - 1;
        if (std::popcount(observed[e]) != high[e] - low[e] + 1) {
            throw std::runtime_error("unit matching slice has an integer gap");
        }
        ++coverage.integer_slices;
    }

    // A real slice vertex of a point hull lies on an edge or is a hull vertex.
    // At a fixed integer e, inspect every straddling pair of observed levels.
    for (int a = 0; a <= width; ++a) {
        if (!observed[a]) continue;
        for (int b = a + 2; b <= width; ++b) {
            if (!observed[b]) continue;
            for (int e = a + 1; e < b; ++e) {
                const int d = b - a;
                const int lower_numerator = (b - e) * low[a] + (e - a) * low[b];
                const int upper_numerator = (b - e) * high[a] + (e - a) * high[b];
                if (!observed[e] || lower_numerator <= d * (low[e] - 1)
                    || upper_numerator >= d * (high[e] + 1)) {
                    throw std::runtime_error("a straddling chord exposes an integer gap");
                }
                ++coverage.chord_checks;
            }
        }
    }
    ++coverage.triples;
    coverage.matching_evaluations += matchings.size();
}

Coverage check_width(int width) {
    const Mask full = (Mask{1} << (width * width)) - 1;
    Coverage coverage;
    std::vector<Mask> ferrers;
    make_ferrers(width, 0, width, 0, ferrers);
    coverage.ferrers = ferrers.size();
    const std::vector<Mask> matchings = unit_matchings(width);
    for (Mask first : ferrers) {
        for (Mask third : ferrers) {
            if (third & ~first) continue;
            ++coverage.outer_pairs;
            for (Mask second : ferrers) {
                if ((third & ~second) || (second & ~first)) continue;
                const Mask prefix = full ^ first ^ second ^ third;
                check_spectrum(width, second, prefix, matchings, coverage);
            }
        }
    }
    return coverage;
}

int main() {
    for (int width = 1; width <= MAX_WIDTH; ++width) {
        const Coverage c = check_width(width);
        std::cout << "{\"width\":" << width
                  << ",\"ferrers\":" << c.ferrers
                  << ",\"outer_pairs\":" << c.outer_pairs
                  << ",\"triples\":" << c.triples
                  << ",\"matching_evaluations\":" << c.matching_evaluations
                  << ",\"integer_slices\":" << c.integer_slices
                  << ",\"chord_checks\":" << c.chord_checks << "}\n";
    }
}

